"""Kernel-level IR with a latency model.

A :class:`KernelOp` is an ordered list of primitive operations, each with a
type, a list of operand value names and a result value name.  The
:class:`LatencyModel` assigns a per-operation latency; the kernel's critical
path latency is modeled as the sum of the latencies of all added operations
(a sequential schedule estimate).
"""


class LatencyModel:
    """Default per-operation latencies (in cycles)."""

    DEFAULT_LATENCIES = {
        "add": 1,
        "sub": 1,
        "mul": 3,
        "div": 10,
        "load": 2,
        "store": 1,
        "cmp": 1,
        "mux": 0,
        "shift": 1,
        "and": 1,
        "or": 1,
        "xor": 1,
    }

    def __init__(self, overrides=None):
        self._latencies = dict(self.DEFAULT_LATENCIES)
        if overrides:
            self._latencies.update(overrides)

    def get_latency(self, op_type):
        """Latency of ``op_type``; unknown operations default to 1."""
        return self._latencies.get(op_type, 1)


class KernelOp:
    """An ordered collection of primitive operations forming a kernel."""

    def __init__(self, name, latency_model=None):
        self.name = name
        self.latency_model = latency_model or LatencyModel()
        # Each record: {"name", "op_type", "operands", "result"}.
        self.operations = []

    def add_operation(self, name, op_type, operands, result):
        """Append an operation to the kernel."""
        self.operations.append({
            "name": name,
            "op_type": op_type,
            "operands": list(operands),
            "result": result,
        })
        return self.operations[-1]

    def total_operations(self):
        """Number of operations added to the kernel."""
        return len(self.operations)

    def critical_path_latency(self):
        """Sum of the latencies of all added operations (0 if none)."""
        return sum(self.latency_model.get_latency(op["op_type"])
                   for op in self.operations)

    def estimated_cycles(self):
        """Estimated cycle count under a sequential schedule."""
        return self.critical_path_latency()

    def __repr__(self):
        return f"KernelOp({self.name!r}, ops={self.total_operations()})"

"""Token-based dataflow execution engine.

A :class:`DataflowGraph` is a network of :class:`DataflowNode` objects
connected by :class:`DataflowEdge` token channels.  ``step()`` performs one
synchronous pass over the nodes in insertion order: any node whose firing
rule is satisfied consumes the tokens on its input edges, fires, and pushes
its output tokens onto its output edges immediately, so a downstream node
later in the order can consume a token produced earlier in the same step.
"""

from dataclasses import dataclass, field
from enum import Enum


class NodeType(Enum):
    OPERATOR = "operator"
    FORK = "fork"
    JOIN = "join"
    MERGE = "merge"
    BRANCH = "branch"
    BUFFER = "buffer"
    SOURCE = "source"
    SINK = "sink"


@dataclass
class DataflowNode:
    name: str
    node_type: NodeType = NodeType.OPERATOR
    latency: int = 1
    num_inputs: int = 1
    num_outputs: int = 1
    operation: str = "nop"
    fired_count: int = 0

    def can_fire(self, input_tokens):
        """Firing rule given token presence (bool) per input edge."""
        nt = self.node_type
        if nt == NodeType.SOURCE:
            return True
        if nt in (NodeType.SINK, NodeType.MERGE):
            return any(input_tokens)
        if nt == NodeType.JOIN:
            return all(input_tokens)
        if nt == NodeType.FORK:
            return len(input_tokens) >= 1 and input_tokens[0]
        if nt == NodeType.BRANCH:
            return len(input_tokens) >= 2 and all(input_tokens[:2])
        if nt == NodeType.BUFFER:
            return len(input_tokens) >= 1 and input_tokens[0]
        # OPERATOR: all of the first num_inputs inputs.
        n = self.num_inputs
        return len(input_tokens) >= n and all(input_tokens[:n])

    def fire(self, input_values):
        """Consume ``input_values`` and produce the output token values."""
        self.fired_count += 1
        nt = self.node_type
        first = input_values[0] if input_values else 0
        if nt == NodeType.SOURCE:
            return [1] * self.num_outputs
        if nt == NodeType.SINK:
            return []
        if nt == NodeType.FORK:
            return [first] * self.num_outputs
        if nt == NodeType.BRANCH:
            cond = input_values[0] if len(input_values) > 0 else 0
            data = input_values[1] if len(input_values) > 1 else 0
            return [data, 0] if cond else [0, data]
        if nt in (NodeType.MERGE, NodeType.JOIN):
            return [first]
        # OPERATOR / BUFFER.
        if self.operation == "add" and len(input_values) >= 2:
            return [input_values[0] + input_values[1]]
        if self.operation == "sub" and len(input_values) >= 2:
            return [input_values[0] - input_values[1]]
        if self.operation == "mul" and len(input_values) >= 2:
            return [input_values[0] * input_values[1]]
        # Default: pass through the first input.
        return [first]


@dataclass
class DataflowEdge:
    """A token channel between two node ports, holding a FIFO of tokens."""

    source: str
    source_port: int
    target: str
    target_port: int
    data_width: int = 32
    tokens: list = field(default_factory=list)

    @property
    def mask(self):
        return (1 << self.data_width) - 1

    def transfer(self, value):
        """Push a token onto the channel, masked to the data width."""
        self.tokens.append(value & self.mask)

    def has_token(self):
        return bool(self.tokens)

    def consume(self):
        """Pop the oldest token; returns None when empty."""
        return self.tokens.pop(0) if self.tokens else None


class DataflowGraph:
    def __init__(self, name):
        self.name = name
        self.nodes = {}          # insertion-ordered: name -> DataflowNode
        self.edges = []          # list[DataflowEdge]
        self.tokens_produced = 0
        self.tokens_consumed = 0

    def add_node(self, node):
        self.nodes[node.name] = node
        return node

    def add_edge(self, src, src_port, dst, dst_port, width=32):
        if src not in self.nodes:
            raise KeyError(f"unknown source node {src!r}")
        if dst not in self.nodes:
            raise KeyError(f"unknown target node {dst!r}")
        edge = DataflowEdge(src, src_port, dst, dst_port, width)
        self.edges.append(edge)
        return edge

    def _in_edges(self, name):
        return sorted((e for e in self.edges if e.target == name),
                      key=lambda e: e.target_port)

    def _out_edges(self, name):
        return sorted((e for e in self.edges if e.source == name),
                      key=lambda e: e.source_port)

    def step(self):
        """One synchronous pass; returns the number of nodes that fired."""
        fired = 0
        for node in self.nodes.values():
            in_edges = self._in_edges(node.name)
            input_tokens = [e.has_token() for e in in_edges]
            if node.node_type == NodeType.SOURCE and not in_edges:
                input_tokens = [True]
            if not node.can_fire(input_tokens):
                continue
            input_values = [e.consume() for e in in_edges if e.has_token()]
            self.tokens_consumed += len(input_values)
            outputs = node.fire(input_values)
            for edge in self._out_edges(node.name):
                if edge.source_port < len(outputs):
                    value = outputs[edge.source_port]
                else:
                    value = outputs[0] if outputs else 0
                edge.transfer(value)
                self.tokens_produced += 1
            fired += 1
        return fired

    def simulate(self, num_cycles):
        """Run ``step()`` until cycles are exhausted or nothing fires."""
        total_fired = 0
        cycles = 0
        for _ in range(num_cycles):
            fired = self.step()
            if fired == 0:
                break
            cycles += 1
            total_fired += fired
        return {
            "cycles": cycles,
            "total_fired": total_fired,
            "tokens_produced": self.tokens_produced,
            "tokens_consumed": self.tokens_consumed,
        }

"""Symbol and type analysis.

:class:`SymbolTable` resolves value names to their defining operations,
either across a :class:`~k_circt.kernel_ir.KernelOp` or across a parsed
MLIR-like op list (operations whose results/operands are ``Value`` objects
with ``name`` attributes, as in ``src/mlir/ir.py``).  It detects undefined
and multiply-defined symbols.

:class:`TypeResolver` maps symbolic types to concrete MLIR-style integer
types (``"i32"`` etc.) and answers signedness/width queries.
"""

import re


class SymbolTable:
    """Maps value names to the operation that defines them."""

    def __init__(self):
        self._definitions = {}   # name -> defining op (first definition)
        self._definition_ops = {}  # name -> list of all defining ops
        self._uses = {}          # name -> list of using ops

    # -- construction -------------------------------------------------------

    def define(self, name, op):
        self._definition_ops.setdefault(name, []).append(op)
        if name not in self._definitions:
            self._definitions[name] = op

    def use(self, name, op):
        self._uses.setdefault(name, []).append(op)

    @classmethod
    def from_kernel(cls, kernel):
        """Build a table from a KernelOp (records with operands/result)."""
        table = cls()
        for op in kernel.operations:
            table.define(op["result"], op)
        for op in kernel.operations:
            for operand in op["operands"]:
                table.use(operand, op)
        return table

    @classmethod
    def from_ops(cls, ops):
        """Build a table from MLIR-like ops with .results/.operands Values.

        Block arguments (values whose owner is not an operation) can be
        passed in via ``externals`` to mark them as defined.
        """
        table = cls()
        for op in ops:
            for result in getattr(op, "results", []):
                table.define(result.name, op)
        for op in ops:
            for operand in getattr(op, "operands", []):
                table.use(operand.name, op)
        return table

    # -- queries ------------------------------------------------------------

    def lookup(self, name):
        """Return the defining op for ``name``, or None if undefined."""
        return self._definitions.get(name)

    def is_defined(self, name):
        return name in self._definitions

    def defined_names(self):
        return list(self._definitions)

    def undefined_symbols(self):
        """Used names that have no defining operation (sorted)."""
        return sorted(n for n in self._uses if n not in self._definitions)

    def multiply_defined(self):
        """Names defined by more than one operation (sorted)."""
        return sorted(n for n, defs in self._definition_ops.items()
                      if len(defs) > 1)

    def users_of(self, name):
        return list(self._uses.get(name, []))


class TypeResolver:
    """Resolves symbolic types to MLIR-style integer types."""

    DEFAULT_TYPE = "i32"

    _SYMBOLIC = {
        "bool": "i1",
        "bit": "i1",
        "byte": "i8",
        "char": "i8",
        "short": "i16",
        "int": "i32",
        "long": "i64",
        "index": "i32",
        "size_t": "i64",
    }

    _INT_RE = re.compile(r"^([sui]?i)(\d+)$")

    def __init__(self, overrides=None):
        self._symbolic = dict(self._SYMBOLIC)
        if overrides:
            self._symbolic.update(overrides)

    def resolve(self, symbolic_type):
        """Map a symbolic type to a concrete MLIR integer type string.

        Already-concrete types (``i8``, ``si32``, ``ui64``) pass through;
        known symbolic names map per the table; anything else falls back to
        the default (``i32``).
        """
        text = str(symbolic_type).strip()
        if self._INT_RE.match(text):
            return text
        return self._symbolic.get(text, self.DEFAULT_TYPE)

    def width(self, type_str):
        """Bit width of a concrete (or symbolic) integer type."""
        resolved = self.resolve(type_str)
        match = self._INT_RE.match(resolved)
        if not match:
            return int(self.DEFAULT_TYPE[1:])
        return int(match.group(2))

    def is_signed(self, type_str):
        """Signedness: ``si*`` signed, ``ui*`` unsigned; plain ``i*`` and
        symbolic integer types are treated as signed two's complement."""
        resolved = self.resolve(type_str)
        if resolved.startswith("ui"):
            return False
        return True

"""The Kimulator: a K-inspired executable trace engine for circuits.

Evaluation proceeds by explicit, named semantic rules in the style of the
K framework: each rule is a function that takes the current configuration
(a cell-like state: signal store, register file, cycle counter) and rewrites
it.  The :class:`Kimulator` loads a small op-list program, applies the rules
step by step, and records a trace of per-cycle state snapshots together with
the names of the rules that fired.

Program format — a list of instruction tuples::

    ("const", dest, value)        # dest = value
    ("add"|"sub"|"mul", dest, a, b)
    ("and"|"or"|"xor", dest, a, b)
    ("mux", dest, cond, a, b)     # dest = a if cond else b
    ("reg", name, src)            # register name <- src at the cycle tick

Operands ``a``/``b``/``cond``/``src`` are either integer literals or value
names, resolved first against the signal store, then the register file.
"""

from dataclasses import dataclass, field


# ---------------------------------------------------------------------------
# Configuration (the K "configuration" of cells)
# ---------------------------------------------------------------------------

@dataclass
class Configuration:
    """Cell-like machine state: signal store, register file, cycle counter."""

    signals: dict = field(default_factory=dict)
    registers: dict = field(default_factory=dict)
    cycle: int = 0

    def snapshot(self):
        return {
            "signals": dict(self.signals),
            "registers": dict(self.registers),
            "cycle": self.cycle,
        }


def _read(config, operand):
    """Resolve an operand: literal int, signal, then register."""
    if isinstance(operand, int):
        return operand
    if operand in config.signals:
        return config.signals[operand]
    if operand in config.registers:
        return config.registers[operand]
    raise KeyError(f"undefined operand {operand!r} at cycle {config.cycle}")


# ---------------------------------------------------------------------------
# Semantic rules (each takes the configuration, rewrites it, returns a value)
# ---------------------------------------------------------------------------

def rule_const(config, dest, value):
    config.signals[dest] = int(value)
    return config.signals[dest]


def rule_add(config, dest, a, b):
    config.signals[dest] = _read(config, a) + _read(config, b)
    return config.signals[dest]


def rule_sub(config, dest, a, b):
    config.signals[dest] = _read(config, a) - _read(config, b)
    return config.signals[dest]


def rule_mul(config, dest, a, b):
    config.signals[dest] = _read(config, a) * _read(config, b)
    return config.signals[dest]


def rule_and(config, dest, a, b):
    config.signals[dest] = _read(config, a) & _read(config, b)
    return config.signals[dest]


def rule_or(config, dest, a, b):
    config.signals[dest] = _read(config, a) | _read(config, b)
    return config.signals[dest]


def rule_xor(config, dest, a, b):
    config.signals[dest] = _read(config, a) ^ _read(config, b)
    return config.signals[dest]


def rule_mux(config, dest, cond, a, b):
    config.signals[dest] = _read(config, a) if _read(config, cond) \
        else _read(config, b)
    return config.signals[dest]


def rule_reg_tick(config, pending):
    """Clock tick: apply pending register updates and advance the cycle."""
    for name, value in pending.items():
        config.registers[name] = value
    config.cycle += 1
    return config


# ---------------------------------------------------------------------------
# Kimulator
# ---------------------------------------------------------------------------

class Kimulator:
    """Loads a program, applies semantic rules step by step, records a trace."""

    RULES = {
        "const": rule_const,
        "add": rule_add,
        "sub": rule_sub,
        "mul": rule_mul,
        "and": rule_and,
        "or": rule_or,
        "xor": rule_xor,
        "mux": rule_mux,
    }

    def __init__(self, program=None, registers=None):
        self.config = Configuration(registers=dict(registers or {}))
        self.program = []
        self.trace = []
        if program:
            self.load(program)

    def load(self, program):
        """Load an op-list program (list of instruction tuples)."""
        self.program = [tuple(instr) for instr in program]

    def load_mlir_module(self, module):
        """Best-effort import of a parsed ``src/mlir`` module.

        Walks the ops of the first ``hw.module`` (or the module body itself)
        and translates hw/comb/seq ops into the op-list program format.
        """
        ops = []
        for top in getattr(module, "ops", []):
            if top.name == "hw.module" and top.regions:
                ops = list(top.regions[0].blocks[0].ops)
                break
        else:
            ops = [op for op in getattr(module, "ops", [])
                   if op.name != "builtin.module"]

        program = []
        for op in ops:
            names = [v.name for v in op.operands]
            result = op.results[0].name if op.results else None
            if op.name == "hw.constant":
                program.append(("const", result, op.attributes["value"]))
            elif op.name in ("comb.add", "comb.sub", "comb.mul",
                             "comb.and", "comb.or", "comb.xor"):
                program.append((op.name.split(".")[1], result, *names[:2]))
            elif op.name == "comb.mux":
                program.append(("mux", result, *names[:3]))
            elif op.name == "seq.compreg":
                # operands: [next, clk, reset?, reset_value?]
                program.append(("reg", result, names[0]))
            # hw.output and anything else: ignored.
        self.load(program)

    def step(self):
        """Execute one cycle: fire each op's rule, then the register tick."""
        fired_rules = []
        pending = {}
        for instr in self.program:
            opcode, args = instr[0], instr[1:]
            if opcode == "reg":
                name, src = args
                pending[name] = _read(self.config, src)
                fired_rules.append("rule_reg")
                continue
            rule = self.RULES.get(opcode)
            if rule is None:
                raise ValueError(f"no semantic rule for op {opcode!r}")
            rule(self.config, *args)
            fired_rules.append(f"rule_{opcode}")
        rule_reg_tick(self.config, pending)
        fired_rules.append("rule_reg_tick")
        self.trace.append({
            "cycle": self.config.cycle,
            "rules": fired_rules,
            "state": self.config.snapshot(),
        })
        return self.config

    def run(self, num_cycles):
        """Run ``num_cycles`` steps; returns the final configuration."""
        for _ in range(num_cycles):
            self.step()
        return self.config

    @property
    def trace_length(self):
        return len(self.trace)

    @property
    def final_state(self):
        return self.config.snapshot()

    def fired_rule_names(self):
        """Flat list of rule names fired across the whole trace."""
        return [name for entry in self.trace for name in entry["rules"]]

